# Agent Hub 웹 콘솔을 제때 AI EC2(jette-ai)에 올린다 — jettellm 배포(run-redeploy.ps1)와 같은 방식(AWS 프로필 + SSM send-command).
# 쓰는 법: PowerShell 에서  powershell -ExecutionPolicy Bypass -File C:\dev\agent\deploy\deploy-console-ssm.ps1
# 기존 제때 AI 컨테이너는 건드리지 않고, 콘솔 컨테이너(agenthub-console, 127.0.0.1:8090)만 추가한다.
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
$region = 'ap-northeast-2'
$jl = 'C:\dev\jettellm'
$env:AWS_PROFILE = (Get-Content (Join-Path $jl 'dist\setup-log\profile.txt') -Raw).Trim()
$env:Path = [Environment]::GetEnvironmentVariable('Path','Machine') + ';' + [Environment]::GetEnvironmentVariable('Path','User')
Push-Location (Join-Path $jl 'deploy\terraform'); try { $id = (terraform output -raw instance_id).Trim() } finally { Pop-Location }
if (-not $id) { $id = 'i-0dcfae8cd1b402048' }
Write-Host "instance=$id profile=$env:AWS_PROFILE"
$b64 = ''
$cmd = "echo $b64 | base64 -d > /tmp/jette-ec2-console.sh && bash /tmp/jette-ec2-console.sh 2>&1 | tail -n 60"
$tmp = [IO.Path]::GetTempFileName()
@{ commands = @($cmd); executionTimeout = @('1800') } | ConvertTo-Json -Compress | Set-Content $tmp -Encoding ASCII
try { $cid = (aws ssm send-command --region $region --instance-ids $id --document-name AWS-RunShellScript --parameters "file://$tmp" --timeout-seconds 60 --query Command.CommandId --output text).Trim() } finally { Remove-Item $tmp -Force }
Write-Host "SSM command=$cid (5~10분)"
do { Start-Sleep 15; $stt = "$(aws ssm get-command-invocation --region $region --command-id $cid --instance-id $id --query Status --output text 2>$null)".Trim(); Write-Host ("status={0} {1}" -f $stt, (Get-Date -Format 'HH:mm:ss')) } while (-not $stt -or $stt -in 'Pending','InProgress','Delayed')
$out = aws ssm get-command-invocation --region $region --command-id $cid --instance-id $id --query StandardOutputContent --output text
$log = 'C:\dev\agent\deploy\console-deploy-log.txt'
$out | Out-File $log -Encoding UTF8
Write-Host $out
Write-Host "결과를 $log 에 저장했습니다."
